export const HTML = "<!doctype html>\n<html lang=\"en\"><head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"theme-color\" content=\"#193e31\">\n<title>BananaGram · A question with handles</title>\n<style>\n:root{--forest:#193e31;--leaf:#33745a;--ink:#233729;--sage:#e5eedc;--paper:#f8f5e9;--gold:#f2d78a;--line:#beccb9;--pink:#a2464d;--muted:#4c6559;--white:#fffef9}\n*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 system-ui,-apple-system,sans-serif}\nheader{background:var(--forest);color:var(--white);padding:18px 0 46px}\n.container{width:min(1080px,calc(100% - 30px));margin:auto}\nnav{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;font-size:.85rem}\nnav a{color:var(--gold)}h1,h2,h3{font-family:Georgia,\"Times New Roman\",serif;letter-spacing:-.035em;line-height:1.09}\nh1{font-size:clamp(3.1rem,8vw,6.3rem);margin:52px 0 20px}h1 em{color:var(--gold);font-style:normal}\nh2{font-size:clamp(2rem,5vw,2.9rem);margin:10px 0 18px}h3{font-size:1.45rem;margin:0 0 14px}\n.hero{font-size:1.12rem;max-width:720px}.eyebrow,.kicker{font-size:.75rem;font-weight:900;letter-spacing:.16em;text-transform:uppercase;color:var(--leaf)}\nheader .eyebrow{color:var(--gold)}\n.warning{margin:-20px auto 23px;position:relative;padding:15px 18px;background:#fff0c7;border-left:5px solid #995335;font-size:.9rem}\nmain section{padding:34px 0}.light{background:var(--sage);border-top:1px solid var(--line);border-bottom:1px solid var(--line)}\n.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.box{border:1px solid var(--line);background:var(--white);padding:20px;min-width:0}.box.emphasis{border:2px solid var(--forest)}\np{margin:10px 0 15px}label{display:block;margin:16px 0 6px;font-weight:800}.hint{font-size:.84rem;color:var(--muted)}\ninput,textarea,select,button{font:inherit}input[type=text],textarea,select{width:100%;border:1px solid #8fa797;border-radius:6px;padding:11px;background:#fff;color:var(--ink)}\ntextarea{min-height:88px;resize:vertical}input:focus-visible,textarea:focus-visible,select:focus-visible,button:focus-visible,a:focus-visible{outline:3px solid var(--pink);outline-offset:2px}\nbutton,.button{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:44px;padding:10px 16px;border-radius:6px;border:1px solid var(--forest);background:var(--forest);color:#fff;font-weight:800;text-decoration:none;cursor:pointer}\nbutton.secondary,.button.secondary{background:transparent;color:var(--forest)}button.gold{background:var(--gold);color:var(--ink);border-color:var(--gold)}button:disabled{opacity:.58;cursor:not-allowed}\n.actions{display:flex;gap:9px;flex-wrap:wrap;margin:16px 0 6px}\nol{padding-left:22px}.steps{display:flex;gap:10px;flex-wrap:wrap}.steps span{font-size:.76rem;font-weight:800;background:#e4eadb;padding:6px 9px;border-radius:14px}\n#gramPreview,#firstYesPreview,#returnPreview,#crossPreview{white-space:pre-wrap;overflow-wrap:anywhere;border:1px solid var(--line);background:#eff5ed;padding:13px;font:13px/1.6 ui-monospace,Consolas,monospace;max-height:360px;overflow:auto}\n#gramPreview{min-height:260px}.status{min-height:24px;color:var(--leaf);font-weight:750;font-size:.9rem}\n.check{display:flex;gap:12px;align-items:flex-start;margin:15px 0}.check input{flex-shrink:0;width:22px;height:22px;accent-color:var(--forest)}.check label{font-weight:500;margin:0}\n.line{border-top:1px solid var(--line);margin:25px 0}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px}.tabs button{background:transparent;color:var(--forest)}.tabs button.selected{background:var(--forest);color:white}\n#traceList,#tensionList{font-size:.88rem;overflow-wrap:anywhere}\n#traceList>div,#tensionList>div{border-top:1px solid var(--line);padding:10px 0}\n.footer{padding:22px 0;background:#112b21;color:#f4f4e5;font-size:.83rem}.footer a{color:var(--gold)}\nstrong.privacy{color:#a34044}.smallprint{font-size:.8rem;color:#506359}.tag{font-size:.8rem;font-weight:850;color:#41624e}\n.hidden[hidden]{display:none!important}\n@media(max-width:760px){.grid{grid-template-columns:1fr}h1{margin-top:33px}main section{padding:24px 0}.box{padding:16px}}\n@media print{header{background:#fff;color:#000;padding-bottom:4px}main section{padding:4px 0}.warning,.actions,.tabs,#traceForm,#tensionForm,#firstYesForm,#returnForm,#crossForm,.footer{display:none!important}.grid{display:block}.box{break-inside:avoid}pre{max-height:none!important}body{font:11pt Georgia,serif}}\n</style></head>\n<body>\n<header><div class=\"container\"><nav><b>THE GARDEN · BANANAGRAM / POCKET 001</b><div><a href=\"https://garden.abundent.org/seven\">Seven-Day Table ↗</a> &nbsp; <a href=\"https://garden.abundent.org/\">Garden ↗</a></div></nav>\n<div class=\"eyebrow\" style=\"margin-top:37px\">A portable question · a voluntary offering · a possible next step</div>\n<h1>Bring a question.<br><em>Leave a door.</em></h1>\n<p class=\"hero\">Start with what matters. Preserve what you heard, what remains uncertain, and what becomes possible next. Prepare one useful action without asking anyone to join an institution.</p>\n<div class=\"steps\"><span>NEED</span><span>OFFER</span><span>IF THIS SUCCEEDS</span><span>TRACE</span><span>TENSION</span><span>FIRST YES</span><span>RETURN</span></div>\n</div></header>\n<div class=\"container\"><div class=\"warning\"><b>This is a private draft workbench, not a community submission form.</b> Everything you type stays in this browser page while it is open; nothing is sent to the server. Closing or reloading the page loses unsaved work. Private downloads stay on your device. Please avoid typing identifying or sensitive information into a shareable proposal.</div></div>\n<main>\n<section><div class=\"container\"><div class=\"kicker\">01 · Say the important thing</div><h2>What can we make possible?</h2>\n<div class=\"grid\"><div class=\"box emphasis\">\n<form id=\"startForm\" autocomplete=\"off\">\n<label for=\"need\">What question, need, or possibility matters?</label><textarea id=\"need\" required minlength=\"12\" maxlength=\"500\" placeholder=\"Example: Is there an upcoming milk sourcing gap at the food shelf?\"></textarea>\n<label for=\"offering\">What might you offer back? <span class=\"hint\">(Entirely optional)</span></label><textarea id=\"offering\" maxlength=\"240\" placeholder=\"Time, a skill, a question, an introduction—or nothing. No one owes repayment.\"></textarea>\n<label for=\"possible\">If this succeeds, what becomes possible next?</label><textarea id=\"possible\" required minlength=\"12\" maxlength=\"300\" placeholder=\"Example: The authorized buyer could compare real eligible choices.\"></textarea>\n<label for=\"question\">One question still unanswered <span class=\"hint\">(optional)</span></label><textarea id=\"question\" maxlength=\"300\" placeholder=\"Example: Would the food shelf director welcome this research?\"></textarea>\n<div class=\"actions\"><button type=\"submit\" class=\"gold\">Plant my Gram</button><button id=\"starter\" type=\"button\" class=\"secondary\">Load fictional starter</button><button id=\"fresh\" type=\"button\" class=\"secondary\">Start fresh</button></div>\n</form><p id=\"startStatus\" class=\"status\" role=\"status\"></p>\n</div><aside class=\"box\"><div class=\"kicker\">Your portable Gram</div><h3>One particular, not a profile</h3><div id=\"gramPreview\" aria-live=\"polite\">Start by planting a question. The Gram stays in this page until you explicitly download it.</div>\n<div class=\"actions\"><button id=\"savePrivate\" class=\"secondary\" type=\"button\" disabled>Download private Gram JSON</button><button id=\"printPrivate\" class=\"secondary\" type=\"button\">Print current view</button></div>\n<p class=\"smallprint\"><strong class=\"privacy\">Private means: don't post this raw file.</strong> It can contain unverified notes and names you typed. Only a separately reviewed redaction should travel outward.</p></aside>\n</div></div></section>\n<section class=\"light\"><div class=\"container\"><div class=\"kicker\">02 · Don't erase the difficult parts</div><h2>Trace and Tension</h2><p>What someone said is not necessarily what happened. A disagreement can remain unresolved while the question travels.</p>\n<div class=\"grid\"><div class=\"box\"><h3>Add a trace</h3><form id=\"traceForm\" autocomplete=\"off\">\n<label for=\"trace\">What was reported, observed, or tested?</label><textarea id=\"trace\" minlength=\"12\" maxlength=\"450\" placeholder=\"An attendee mentioned a potential change in grant-funded milk support.\"></textarea>\n<label for=\"traceType\">How do we know?</label><select id=\"traceType\"><option value=\"heard_from_someone\">Someone reported it (unverified)</option><option value=\"observed_by_author\">I observed it (self-report)</option><option value=\"document_unreviewed\">A document suggests it (not independently verified)</option><option value=\"local_test\">I tried it locally (not a field proof)</option></select>\n<button type=\"submit\">Add trace</button></form><div id=\"traceList\" aria-live=\"polite\"><p class=\"hint\">No traces yet.</p></div></div>\n<div class=\"box\"><h3>Preserve a tension</h3><form id=\"tensionForm\" autocomplete=\"off\">\n<label for=\"oneView\">One understanding</label><textarea id=\"oneView\" minlength=\"10\" maxlength=\"320\" placeholder=\"The grant is ending.\"></textarea>\n<label for=\"otherView\">Another possibility</label><textarea id=\"otherView\" minlength=\"10\" maxlength=\"320\" placeholder=\"Some purchasing options might remain available.\"></textarea>\n<label for=\"unresolved\">What would resolve this?</label><textarea id=\"unresolved\" minlength=\"10\" maxlength=\"320\" placeholder=\"Ask the authorized purchaser about the program and current allocation.\"></textarea>\n<button type=\"submit\">Hold both, without deciding</button></form><div id=\"tensionList\" aria-live=\"polite\"><p class=\"hint\">No tensions yet.</p></div></div></div>\n<p id=\"observeStatus\" class=\"status\" role=\"status\"></p>\n</div></section>\n<section><div class=\"container\"><div class=\"kicker\">03 · One authorized direction</div><h2>First Yes: one useful act</h2>\n<div class=\"grid\"><div class=\"box\"><form id=\"firstYesForm\" autocomplete=\"off\">\n<label for=\"prepare\">What could be prepared without someone else's permission?</label><textarea id=\"prepare\" minlength=\"12\" maxlength=\"320\" placeholder=\"A blank buyer comparison worksheet, with prices left unknown.\"></textarea>\n<label for=\"permission\">What must be asked before doing anything consequential?</label><textarea id=\"permission\" minlength=\"12\" maxlength=\"320\" placeholder=\"Ask the buyer if a private milk sourcing comparison is welcome.\"></textarea>\n<label for=\"proof\">What would count as a truthful return?</label><textarea id=\"proof\" minlength=\"12\" maxlength=\"320\" placeholder=\"Worksheet prepared; answer is yes, no, or not yet.\"></textarea>\n<button type=\"submit\">Select a First Yes plan</button></form><p id=\"firstYesStatus\" class=\"status\" role=\"status\"></p></div>\n<div class=\"box\"><h3>Selected ≠ authorized</h3><div id=\"firstYesPreview\" class=\"hint\">Your chosen plan will appear here. Selecting is not executing, purchasing, scheduling, enrolling, or confirming anything.</div></div></div>\n</div></section>\n<section class=\"light\"><div class=\"container\"><div class=\"kicker\">04 · Let the work end honestly</div><h2>Fruit, Seed, Compost</h2>\n<div class=\"grid\"><div class=\"box\"><form id=\"returnForm\" autocomplete=\"off\">\n<label for=\"fruit\">Fruit: what actually changed? <span class=\"hint\">(Your own report, not independently confirmed)</span></label><textarea id=\"fruit\" maxlength=\"300\" placeholder=\"A draft worksheet was prepared. No actual sourcing was confirmed.\"></textarea>\n<label for=\"seed\">Seed: what might be worth trying next?</label><textarea id=\"seed\" maxlength=\"300\" placeholder=\"With permission, verify the current sourcing program.\"></textarea>\n<label for=\"compost\">Compost: what assumption failed or remains unresolved?</label><textarea id=\"compost\" maxlength=\"300\" placeholder=\"We still don't know whether the grant is ending.\"></textarea>\n<button type=\"submit\">Record a local return</button></form><p id=\"returnStatus\" class=\"status\" role=\"status\"></p></div>\n<div class=\"box\"><h3>A seed isn't a successor</h3><div id=\"returnPreview\" class=\"hint\">A return doesn't automatically create another task or transfer anybody's authority.</div></div></div>\n</div></section>\n<section><div class=\"container\"><div class=\"kicker\">05 · A carefully chosen crossing</div><h2>Carry the question, not the private history</h2>\n<div class=\"grid\"><div class=\"box\"><form id=\"crossForm\" autocomplete=\"off\">\n<p>Write a <b>new, public-safe redaction</b>. Private traces, tensions, contacts, and the raw Gram will not be copied automatically. This is a proposal to a future recipient, not a public post.</p>\n<label for=\"redaction\">The one safe sentence you choose to carry</label><textarea id=\"redaction\" maxlength=\"240\" minlength=\"12\" placeholder=\"Would a willing food-shelf steward welcome a comparison of permitted milk sourcing options?\"></textarea>\n<label for=\"destination\">Potential next doorway</label><select id=\"destination\"><option value=\"first-yes\">First Yes — draft a possible useful action</option><option value=\"campfire-review\">Campfire — invite a willing steward to review</option><option value=\"telegram-porch-draft\">Telegram porch — create a draft, not send</option></select>\n<div class=\"check\"><input type=\"checkbox\" id=\"authorOwn\"><label for=\"authorOwn\">I am the author of this proposed contribution and I am choosing to submit the redacted question for consideration.</label></div>\n<div class=\"check\"><input type=\"checkbox\" id=\"consent\"><label for=\"consent\">I choose to export exactly this redacted text. I understand it may be shared after I deliberately hand it to someone.</label></div>\n<div class=\"check\"><input type=\"checkbox\" id=\"reviewed\"><label for=\"reviewed\">I checked the redaction for names, contact information, private details, and unverified claims, and I am satisfied with how it is worded.</label></div>\n<div class=\"actions\"><button type=\"submit\">Prepare an inert handoff</button><button type=\"button\" id=\"downloadHandoff\" class=\"secondary\" disabled>Download proposal JSON</button><button type=\"button\" id=\"returnToTableBtn\" class=\"gold\" hidden disabled>Return reviewed question to my Table</button></div><p class=\"smallprint\" id=\"tableReturnHint\" hidden>Opened by your private Seven-Day Table seat. This sends one reviewed sentence to that original tab only; it will be an editable, unsent draft. It does not opt into sharing or submit a contribution.</p>\n</form><p id=\"crossStatus\" class=\"status\" role=\"status\"></p></div>\n<div class=\"box\"><h3>A door, not a command</h3><div id=\"crossPreview\" class=\"hint\">Nothing crosses automatically. If you deliberately download the reviewed proposal, another authorized system or steward would still need to accept it.</div>\n<div class=\"line\"></div><p class=\"tag\">STATUS: local / experimental / no backend</p><p>Nothing in this prototype sends a message, records a donation, confirms milk delivery, invokes an AI model, enrolls a person, or modifies the Jubilee ledger.</p>\n<div class=\"actions\"><a class=\"button secondary\" href=\"https://garden.abundent.org/seven\">Visit the Seven-Day Table</a></div>\n</div></div></div></section>\n<section class=\"light\" id=\"forest\"><div class=\"container\">\n<div class=\"kicker\">06 · Forest View · a possible path, not a people graph</div>\n<h2>What can grow from what happened?</h2>\n<p>One reviewed question can become an evidence-labeled, read-only <strong>Free Graph packet</strong> and a voluntary invitation to another table. The result stays unconfirmed without an independently verified receipt. Nothing here joins people, publishes information, or starts a table automatically.</p>\n<div class=\"grid\">\n <div class=\"box emphasis\">\n <h3>Make a public-safe forest seed</h3>\n <p class=\"hint\">First, prepare a reviewed redacted question in Step 05. Then separately write only what you're comfortable including in a portable packet.</p>\n <form id=\"forestForm\" autocomplete=\"off\">\n <label for=\"forestFruit\">Fruit · your account of something that happened (optional; not independently verified)</label>\n <textarea id=\"forestFruit\" maxlength=\"240\" placeholder=\"A blank comparison worksheet was drafted; no food was bought or delivered.\"></textarea>\n <label for=\"forestSeed\">Seed · one possible next question (optional)</label>\n <textarea id=\"forestSeed\" maxlength=\"240\" placeholder=\"Would a willing purchaser like to verify one specific sourcing option?\"></textarea>\n <p class=\"hint\">Enter fruit, seed, or both. Private traces and tensions are never automatically copied into the packet.</p>\n <label class=\"check\"><input type=\"checkbox\" id=\"forestReviewed\"><span>I reviewed the exact question, fruit and seed above for accuracy, uncertainty and private information.</span></label>\n <label class=\"check\"><input type=\"checkbox\" id=\"forestConsent\"><span>I approve preparing a portable, public-safe graph packet from only these redacted fields. This does not publish it.</span></label>\n <div class=\"actions\"><button type=\"submit\" class=\"gold\">Grow my private Forest View</button><button type=\"button\" id=\"forestDownload\" class=\"secondary\" disabled>Download Free Graph packet</button></div>\n </form>\n <p id=\"forestStatus\" class=\"status\" role=\"status\"></p>\n </div>\n <div class=\"box\"><h3>A little forest of possibilities</h3>\n <div id=\"forestDiagram\" aria-live=\"polite\" style=\"padding:15px;background:#e4eddc;border:1px solid #b8cbb3;min-height:155px\">\n <p class=\"hint\">A reviewed question can branch into author-reported fruit and an optional next seed. No people are mapped.</p>\n </div>\n <p class=\"smallprint\">Free Graph's five portable link verbs remain unchanged. This produces a content-addressed <em>seed projection</em>, not a project-owned truth or verified Jubilee consequence.</p>\n </div>\n</div>\n<div class=\"grid\" style=\"margin-top:18px\">\n <div class=\"box\">\n <h3>Make the next invitation—only if someone wants to</h3>\n <p>A new table does not inherit the previous table's participants or obligations. It starts with a fresh invitation and a new human decision.</p>\n <form id=\"forestNextForm\" autocomplete=\"off\">\n <label for=\"forestNextTitle\">New table title</label><input id=\"forestNextTitle\" type=\"text\" minlength=\"3\" maxlength=\"84\" value=\"The Next Table · One Useful Question\">\n <label for=\"forestNextQuestion\">Public-safe invitation question (editable)</label>\n <textarea id=\"forestNextQuestion\" minlength=\"5\" maxlength=\"270\" placeholder=\"What might willing neighbors clarify or make possible together?\"></textarea>\n <label for=\"forestNextDate\">Suggested date for the new table</label>\n <input id=\"forestNextDate\" type=\"date\">\n <label class=\"check\"><input type=\"checkbox\" id=\"forestNextApproval\"><span>I approve these exact public-safe title, question and date for an independent invitation link. No one is enrolled.</span></label>\n <div class=\"actions\"><button type=\"submit\" class=\"gold\">Prepare a voluntary invitation</button><button type=\"button\" class=\"secondary\" id=\"forestCopyInvite\" disabled>Copy link</button></div>\n </form>\n <a id=\"forestNextLink\" href=\"https://abundent.org/tables/\" class=\"button secondary\" target=\"_blank\" rel=\"noopener noreferrer\" referrerpolicy=\"no-referrer\" hidden>Open prepared Seventh Table invitation ↗</a>\n <p id=\"forestNextStatus\" class=\"status\" role=\"status\"></p>\n </div>\n <div class=\"box\">\n <h3>Why this isn't an automatic network</h3>\n <p>People cannot be indexed from private history merely because they were mentioned. A reported result stays a self-report. A seed stays a possibility. A graph relation stays a proposed relation.</p>\n <p>Only if somebody chooses to open the prepared invitation does the question leave this page. The destination can propose another table; no invitations are sent from here.</p>\n <div id=\"forestPacketStatus\" class=\"hint\">No portable packet prepared.</div>\n </div>\n</div>\n</div></section>\n<section id=\"field\" class=\"light\"><div class=\"container\"><div class=\"kicker\">07 · FIELD RETURN · Human confirmation belongs to the owner</div>\n<h2>What would make this real?</h2><p>This is a <strong>local witness-request worksheet</strong>, not a claim that anybody has already helped. You can prepare a public-safe question for a willing, authorized steward. You can also inspect a manually entered source-status claim without promoting it to verified provision.</p>\n<div class=\"grid\">\n <div class=\"box emphasis\">\n <h3>Ask for a real-world check</h3>\n <form id=\"fieldRequestForm\" autocomplete=\"off\">\n <label for=\"fieldAsk\">One question for the person responsible</label>\n <textarea id=\"fieldAsk\" minlength=\"12\" maxlength=\"240\" placeholder=\"Would the food shelf purchaser welcome a private comparison of current ordering options?\"></textarea>\n <label for=\"fieldProof\">What independent observation or owner receipt would settle this?</label>\n <textarea id=\"fieldProof\" minlength=\"12\" maxlength=\"240\" placeholder=\"Buyer confirms the actual supply terms, or authenticated recipient confirms a real delivery.\"></textarea>\n <label for=\"fieldFog\">What must we not assume yet?</label>\n <textarea id=\"fieldFog\" minlength=\"12\" maxlength=\"240\" placeholder=\"Whether a grant ends, the source quantity, and whether any new milk was delivered.\"></textarea>\n <label class=\"check\"><input type=\"checkbox\" id=\"fieldApproved\"><span>I choose to prepare this one public-safe question for human review. No recipient has agreed, and this doesn't send anything.</span></label>\n <div class=\"actions\"><button type=\"submit\" class=\"gold\">Prepare witness question</button><button type=\"button\" class=\"secondary\" id=\"fieldCopy\" disabled>Copy a voluntary invitation</button><button type=\"button\" class=\"secondary\" id=\"fieldDownload\" disabled>Save request JSON</button></div>\n </form><p id=\"fieldRequestStatus\" class=\"status\" role=\"status\"></p>\n </div>\n <div class=\"box\"><h3>A report isn't a confirmation</h3>\n <div id=\"fieldRequestPreview\" style=\"white-space:pre-wrap;background:#eff5ed;border:1px solid #beccb9;padding:15px;min-height:165px\">First make an explicitly reviewed Forest packet in Step 06, then prepare a question for the person authorized to answer it.</div>\n <p class=\"smallprint\">A person reporting that they delivered food does not prove the recipient received it. A receipt ID alone does not prove two records represent different physical deliveries. Declining to participate is a valid outcome.</p>\n </div>\n</div>\n<div class=\"grid\" style=\"margin-top:18px\">\n<div class=\"box\"><h3>Check a reported return</h3>\n <p class=\"hint\">Optional field exercise: manually transcribe only non-sensitive claimed quantities. This does not query BananaSpork or Supabase, authenticate anyone, or verify a real delivery.</p>\n <form id=\"fieldCheckForm\" autocomplete=\"off\">\n <label for=\"fieldSteward\">Steward's response (as reported)</label>\n <select id=\"fieldSteward\"><option value=\"not-asked\">Not asked yet</option><option value=\"accepted-to-review\">Agreed to review the question</option><option value=\"declined\">Declined</option><option value=\"no-need\">No current need</option></select>\n <label for=\"fieldRequirement\">What particular requirement is being checked?</label><input id=\"fieldRequirement\" type=\"text\" minlength=\"5\" maxlength=\"160\" value=\"One hypothetical milk need\">\n <div class=\"grid\">\n <div><label for=\"fieldQuantity\">Requested quantity</label><input id=\"fieldQuantity\" type=\"number\" min=\"0\" step=\"any\" value=\"24\"></div>\n <div><label for=\"fieldUnit\">Unit</label><input id=\"fieldUnit\" type=\"text\" maxlength=\"36\" value=\"cartons\"></div>\n </div>\n <label for=\"fieldReported\">Quantity helper says they delivered</label><input id=\"fieldReported\" type=\"number\" min=\"0\" step=\"any\" value=\"0\">\n <label for=\"fieldConfirmed\">Quantity source record claims the recipient confirmed</label><input id=\"fieldConfirmed\" type=\"number\" min=\"0\" step=\"any\" value=\"0\">\n <label for=\"fieldOccurrence\">Physical occurrence reference, if legitimately available <span class=\"hint\">(optional; don't enter a name or token)</span></label><input id=\"fieldOccurrence\" type=\"text\" maxlength=\"96\" placeholder=\"example-occurrence-001\">\n <label class=\"check\"><input type=\"checkbox\" id=\"fieldSecondEnabled\"><span>The same underlying requirement has a second Campfire link (do not double-count).</span></label>\n <div id=\"fieldSecondFields\" hidden>\n <label for=\"fieldSecondConfirmed\">Second link's claimed confirmed quantity</label><input id=\"fieldSecondConfirmed\" type=\"number\" min=\"0\" step=\"any\" value=\"0\">\n <label for=\"fieldSecondOccurrence\">Second link occurrence reference (optional)</label><input id=\"fieldSecondOccurrence\" type=\"text\" maxlength=\"96\" placeholder=\"example-occurrence-001\">\n </div>\n <label class=\"check\"><input type=\"checkbox\" id=\"fieldStatusFresh\"><span>I have reason to believe this source status is current (still not verified by this page).</span></label>\n <div class=\"actions\"><button type=\"submit\">Inspect this claim conservatively</button></div>\n </form><p id=\"fieldCheckStatus\" class=\"status\" role=\"status\"></p>\n </div>\n <div class=\"box\"><h3>What is actually established?</h3>\n <div id=\"fieldReviewPreview\" style=\"white-space:pre-wrap;background:#eff5ed;border:1px solid #beccb9;padding:15px;min-height:165px\">No source status has been inspected here.</div>\n <div class=\"line\"></div><p class=\"tag\">HUMAN DECISION REQUIRED</p>\n <p>Only a valid authorization and receipt from the owning system, with the relevant recipient's confirmation, can establish an actual fulfilled need. This worksheet does not perform those checks.</p>\n <div class=\"actions\"><button type=\"button\" id=\"fieldReviewDownload\" class=\"secondary\" disabled>Download private review</button></div>\n </div>\n</div>\n</div></section>\n<section id=\"field-trial\"><div class=\"container\">\n<div class=\"kicker\">08 · THE FIRST REAL CAMPFIRE</div>\n<h2>Two willing members. One independent outsider. One honest return.</h2>\n<p>We're ready to test the part software cannot pretend happened. This experiment requires actual separate accounts and the intentionally selected NanaSpork project. <strong>Nothing in this page creates those accounts, tests their access, enrolls a household, or certifies a delivery.</strong></p>\n<div class=\"grid\">\n <div class=\"box emphasis\"><h3>Invite two people to test a boundary</h3>\n <p>One participant joins your small private Campfire. A second, nonmember tester independently attempts to access it and should be refused. Nobody shares passwords or needs to disclose a personal hardship.</p>\n <p class=\"hint\">Not a public recruitment campaign or aid request. This is a proposed voluntary test with synthetic messages and an optional, separately permissioned real-world Help Slip.</p>\n <div class=\"actions\"><button type=\"button\" id=\"fieldTrialCopy\">Copy a short invitation for testers</button><a class=\"button secondary\" href=\"https://github.com/the-static-collective/BananaSpork/blob/feat/field-specimen-independent-proof-002/docs/field-specimen-002.md\" target=\"_blank\" rel=\"noopener noreferrer\">Open the full field card ↗</a></div>\n <p id=\"fieldTrialStatus\" class=\"status\" role=\"status\"></p>\n </div>\n <div class=\"box\"><h3>When does the test count?</h3>\n <ol>\n  <li><strong>Separate sessions:</strong> two real members message, the nonmember cannot read or post.</li>\n  <li><strong>Durable:</strong> the exchange survives restarting the application.</li>\n  <li><strong>Faithful:</strong> importing the same Help Slip twice doesn't create a second underlying need.</li>\n  <li><strong>Honest:</strong> a helper's report doesn't reduce a need until the recipient actually confirms it.</li>\n  <li><strong>Reversible:</strong> one unresolved item stays unresolved; nobody is assigned a successor task.</li>\n </ol>\n <p class=\"hint\">We now have our own <a href=\"https://github.com/the-static-collective/BananaSpork/pull/20\" target=\"_blank\" rel=\"noopener noreferrer\">first-party Campfire backend</a>: persistent SQLite, invite-only accounts, ordinary messages, report and owner-acceptance records. This is source and local-service software, <strong>not yet a publicly hosted remote service</strong>. No independent physical delivery or three-person field trial has been confirmed.</p><p><a class=\"button secondary\" href=\"https://github.com/the-static-collective/BananaSpork/blob/feat/campfire-selfhost-backend-001/campfire-backend/README.md\" target=\"_blank\" rel=\"noopener noreferrer\">Run our own backend ↗</a></p>\n </div>\n</div>\n</div></section>\n</main>\n<footer class=\"footer\"><div class=\"container\">BANANAGRAM POCKET 001 · A Static Collective / GRAFT re-entry experiment. A question can travel; authority must be granted locally. <a href=\"https://github.com/the-static-collective/GRAFT/pull/2\">Source and status</a></div></footer>\n<script type=\"module\" src=\"?asset=app\"></script>\n</body></html>\n";
export const APP = "import {createGram,addTrace,addTension,selectFirstYes,makeReturn,formatCard} from '?asset=gram';\nimport {proposeGramCrossing} from '?asset=reentry';\nimport {composeForest,nextInvitation} from '?asset=forest';\nimport {prepareFieldRequest,inspectClaimedEvidence} from '?asset=witness';\n\nconst $=(id)=>document.getElementById(id);\nconst value=(id)=>$(id).value.trim();\nconst tell=(id,msg)=>{$(id).textContent=msg;};\nlet gram=null,plan=null,returned=null,handoff=null,forest=null,successor=null,fieldRequest=null,fieldReview=null;\nconst tableNonce=new URLSearchParams(location.hash.slice(1)).get('returnToTable');\nconst tableReturnMode=!!(window.opener&&tableNonce&&/^[a-f0-9]{32}$/.test(tableNonce));\nconst TABLE_MESSAGE='bananagram.reviewed-seat-draft/v0';\nif(tableReturnMode){\n $('returnToTableBtn').hidden=false;\n $('tableReturnHint').hidden=false;\n}\nfunction syncReturnButton(){\n $('returnToTableBtn').disabled=!tableReturnMode||!handoff;\n}\nconst newRef=()=>{\n const u=crypto.randomUUID?.();\n if(u) return 'gram:'+u;\n const bytes=crypto.getRandomValues(new Uint8Array(16));\n return 'gram:'+Array.from(bytes,x=>x.toString(16).padStart(2,'0')).join('');\n};\nfunction privateDownload(filename,body){\n const blob=new Blob([body],{type:'application/json;charset=utf-8'});\n const url=URL.createObjectURL(blob),a=document.createElement('a');\n a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();\n setTimeout(()=>URL.revokeObjectURL(url),1200);\n}\nfunction clearInvitation(reason=''){\n successor=null;\n $('forestNextLink').hidden=true;\n $('forestCopyInvite').disabled=true;\n $('forestNextApproval').checked=false;\n tell('forestNextStatus',reason);\n}\nfunction clearField(reason=''){\n fieldRequest=null;fieldReview=null;\n $('fieldDownload').disabled=true;$('fieldCopy').disabled=true;$('fieldReviewDownload').disabled=true;\n tell('fieldRequestPreview','No reviewed witness question prepared. This page does not certify anybody or anything.');\n tell('fieldReviewPreview','No source status independently verified.');\n tell('fieldRequestStatus',reason);tell('fieldCheckStatus','');\n}\nfunction clearForest(reason=''){\n clearField('Forest changed. Review a new witness question to continue.');\n forest=null;\n $('forestDownload').disabled=true;\n tell('forestPacketStatus','No portable packet prepared.');\n $('forestDiagram').replaceChildren();\n const note=document.createElement('p');note.className='hint';\n note.textContent='No reviewed forest seed yet. Your private Gram is not a shared graph.';\n $('forestDiagram').append(note);\n tell('forestStatus',reason);\n clearInvitation();\n}\nfunction invalidateDownstream(){\n clearForest('Source revision changed. Review a fresh handoff before building a Forest.');\n plan=null;returned=null;handoff=null;\n tell('firstYesPreview','This Gram has changed. Select a fresh First Yes plan if useful.');\n tell('returnPreview','This Gram has changed. A return must reference the latest revision.');\n tell('crossPreview','The Gram has changed. Review and prepare another redaction if you want to export it.');\n $('downloadHandoff').disabled=true;syncReturnButton();\n tell('crossStatus','');\n}\nfunction updateList(id,items,formatter){\n const root=$(id);\n root.replaceChildren();\n if(!items.length){const p=document.createElement('p');p.className='hint';p.textContent='None recorded yet.';root.append(p);return;}\n items.forEach((v,i)=>{\n const div=document.createElement('div');div.textContent=(i+1)+'. '+formatter(v);root.append(div);\n });\n}\nfunction render(){\n $('savePrivate').disabled=!gram;\n if(!gram){tell('gramPreview','Start by planting a question. The Gram stays in this page until you explicitly download it.');updateList('traceList',[],()=> '');updateList('tensionList',[],()=> '');return;}\n tell('gramPreview',formatCard(gram,returned));\n updateList('traceList',gram.trace,x=>x.statement+' — '+x.sourceType.replaceAll('_',' '));\n updateList('tensionList',gram.tensions,x=>x.oneView+' / '+x.otherView+' · OPEN: '+x.unresolvedQuestion);\n}\nfunction grow(fn){\n if(!gram){tell('observeStatus','Plant your Gram first.');return;}\n try{gram=fn(gram);invalidateDownstream();render();tell('observeStatus','Preserved a new local revision ('+gram.revision+'). Your earlier snapshot was not silently overwritten.');}\n catch(err){tell('observeStatus',err.message||'Could not update Gram.');}\n}\n$('startForm').addEventListener('submit',e=>{\n e.preventDefault();\n if(!$('startForm').reportValidity())return;\n try{\n  const first=createGram({sourceRef:newRef(),kind:'question',\n   need:value('need'),offeringBack:value('offering'),ifThisSucceeds:value('possible'),question:value('question')});\n  if(gram&&!confirm('Replace your current unsaved Gram with a new one? Download it privately first if you want to keep it.'))return;\n  gram=first;invalidateDownstream();render();\n  tell('startStatus','Gram planted on this device. Revision 1. No contact, promise, or outside record created.');\n }catch(err){tell('startStatus',err.message||'Could not create Gram.');}\n});\n$('starter').addEventListener('click',()=>{\n $('need').value='Could a willing food shelf buyer benefit from a verified comparison of milk sourcing options?';\n $('offering').value='If helpful, share a public-safe research method with other communities, subject to consent.';\n $('possible').value='An authorized buyer can choose a suitable option without relying on rumors or guessed prices.';\n $('question').value='Which program, quantities, conditions and dates are currently verified?';\n tell('startStatus','Fictional research starter loaded. It is not a claim about an actual food shelf.');\n});\n$('fresh').addEventListener('click',()=>{\n if(gram&&!confirm('Start fresh? Unsaved work in this browser page will be lost.'))return;\n gram=null;plan=null;returned=null;handoff=null;\n for(const form of ['startForm','traceForm','tensionForm','firstYesForm','returnForm','crossForm'])$(form).reset();\n $('downloadHandoff').disabled=true;syncReturnButton();\n for(const id of ['startStatus','observeStatus','firstYesStatus','returnStatus','crossStatus'])tell(id,'');\n tell('firstYesPreview','Your chosen plan will appear here. Selecting is not executing, purchasing, scheduling, enrolling, or confirming anything.');\n tell('returnPreview','A return does not create another task or transfer authority.');\n tell('crossPreview','Nothing crosses automatically. An authorized person would still need to accept the proposal.');\n render();\n});\n$('traceForm').addEventListener('submit',e=>{\n e.preventDefault();if(!e.target.reportValidity())return;\n grow(g=>addTrace(g,{statement:value('trace'),sourceType:value('traceType')}));\n e.target.reset();\n});\n$('tensionForm').addEventListener('submit',e=>{\n e.preventDefault();if(!e.target.reportValidity())return;\n grow(g=>addTension(g,{oneView:value('oneView'),otherView:value('otherView'),unresolvedQuestion:value('unresolved')}));\n e.target.reset();\n});\n$('firstYesForm').addEventListener('submit',e=>{\n e.preventDefault();if(!gram){tell('firstYesStatus','Plant a Gram first.');return;}\n if(!e.target.reportValidity())return;\n try{\n  plan=selectFirstYes(gram,{selected:true,prepareNow:value('prepare'),\n   permissionQuestion:value('permission'),proofOfReturn:value('proof')});\n  tell('firstYesPreview',JSON.stringify(plan,null,2));\n  tell('firstYesStatus','Plan selected locally. No task assigned, message sent, or authorization granted.');\n }catch(err){tell('firstYesStatus',err.message);}\n});\n$('returnForm').addEventListener('submit',e=>{\n e.preventDefault();if(!gram){tell('returnStatus','Plant a Gram first.');return;}\n try{\n  returned=makeReturn(gram,{reviewed:true,fruit:value('fruit'),seed:value('seed'),compost:value('compost')});\n  tell('returnPreview',JSON.stringify(returned,null,2));\n  tell('returnStatus','Your local account of fruit, seed and compost is saved in this page. No claim of independent verification.');\n  render();\n }catch(err){tell('returnStatus',err.message);}\n});\n$('crossForm').addEventListener('submit',e=>{\n e.preventDefault();\n if(!gram){tell('crossStatus','Plant your Gram first.');return;}\n if(!e.target.reportValidity())return;\n try{\n  const result=proposeGramCrossing(gram,{\n   participationConfirmedByAuthor:$('authorOwn').checked,\n   consentToExport:$('consent').checked,\n   reviewedByHuman:$('reviewed').checked,\n   redactedSummary:value('redaction'),kind:'question',destination:value('destination')\n  });\n  handoff=result.standing==='PROPOSE_ONLY'?result:null;\n  tell('crossPreview',JSON.stringify(result,null,2));\n  $('downloadHandoff').disabled=!handoff;syncReturnButton();\n  clearForest('Reviewed redaction changed. Compose the forest again.');\n  tell('crossStatus',handoff?'A proposal-only packet is ready. Download it deliberately if you choose. No message has been sent.':\n   'HOLD: author submission, export consent and redaction review are all required.');\n }catch(err){handoff=null;$('downloadHandoff').disabled=true;syncReturnButton();clearForest('Cannot export an unreviewed question.');tell('crossStatus',err.message||'Unable to prepare redaction.');}\n});\n$('savePrivate').addEventListener('click',()=>{\n if(!gram)return;\n if(!confirm('Download the COMPLETE PRIVATE Gram? It may include unverified statements or personal notes. Do not publish or forward this raw file.'))return;\n const out={schema:'bananagram.private-local-export/v0',\n  warning:'PRIVATE DEVICE EXPORT; not a public proposal or independently verified Jubilee receipt',\n  gram,firstYesPlan:plan,localReturn:returned};\n privateDownload('bananagram-private-'+gram.sourceRef.replace(/[^a-z0-9-]/gi,'-')+'.json',JSON.stringify(out,null,2));\n tell('startStatus','Private draft downloaded to your device; it was not uploaded or sent.');\n});\n$('downloadHandoff').addEventListener('click',()=>{\n if(!handoff)return;\n // Re-check that this remains the particular reviewed redaction.\n const current=proposeGramCrossing(gram,{participationConfirmedByAuthor:$('authorOwn').checked,\n   consentToExport:$('consent').checked,reviewedByHuman:$('reviewed').checked,\n   redactedSummary:value('redaction'),kind:'question',destination:value('destination')});\n if(current.standing!=='PROPOSE_ONLY'||JSON.stringify(current)!==JSON.stringify(handoff)){\n  handoff=null;$('downloadHandoff').disabled=true;syncReturnButton();clearForest('Source approval changed.');\n  tell('crossStatus','Something changed. Review and prepare the redaction again.');return;\n }\n privateDownload('bananagram-reviewed-proposal.json',JSON.stringify(handoff,null,2));\n tell('crossStatus','Proposal packet downloaded locally. No message or submission was sent.');\n});\nfor(const id of ['redaction','destination','authorOwn','consent','reviewed']){\n $(id).addEventListener('input',()=>{\n  handoff=null;$('downloadHandoff').disabled=true;syncReturnButton();clearForest('Redaction changed; forest review must be repeated.');\n  tell('crossStatus','Draft changed; prepare and review again before exporting.');\n });\n}\n$('returnToTableBtn').addEventListener('click',()=>{\n if(!tableReturnMode||!handoff||!window.opener||window.opener.closed){\n  tell('crossStatus','Your original Table tab is not available. Keep this private draft and use its separate download if you want.');\n  return;\n }\n try{\n  const current=proposeGramCrossing(gram,{\n   participationConfirmedByAuthor:$('authorOwn').checked,\n   consentToExport:$('consent').checked,\n   reviewedByHuman:$('reviewed').checked,\n   redactedSummary:value('redaction'),kind:'question',destination:value('destination')\n  });\n  if(current.standing!=='PROPOSE_ONLY'||JSON.stringify(current)!==JSON.stringify(handoff))\n   throw Error('The reviewed draft changed. Prepare it again first.');\n  const summary=current.candidate?.summary;\n  if(typeof summary!=='string'||summary.length<12||summary.length>240)\n   throw Error('Only a short reviewed question can return to the Table.');\n  window.opener.postMessage({type:TABLE_MESSAGE,nonce:tableNonce,\n    standing:'PROPOSE_ONLY',summary},location.origin);\n  tell('crossStatus','The reviewed question was offered to your original Table tab as an editable draft. No contribution was saved or shared.');\n }catch(err){tell('crossStatus',err.message||'Unable to return the draft.');}\n});\nfunction forestNode(label,value,metadata){\n const article=document.createElement('div');\n article.style.cssText='border:1px solid #c0d0ba;padding:12px;margin:9px 0;border-radius:6px;background:#fffef8';\n const h=document.createElement('strong');h.textContent=label;article.append(h);\n const body=document.createElement('p');body.textContent=value;article.append(body);\n const small=document.createElement('small');small.textContent=metadata;article.append(small);\n $('forestDiagram').append(article);\n}\nfunction renderForest(){\n $('forestDiagram').replaceChildren();\n if(!forest)return;\n forestNode('QUESTION · UNRESOLVED',forest.question,'Portable question / author reviewed / no owner adoption');\n if(forest.fruit)forestNode('FRUIT · AUTHOR REPORT',forest.fruit,'Not independently witnessed or confirmed');\n if(forest.seed)forestNode('SEED · POSSIBILITY',forest.seed,'No automatic next table or successor authority');\n $('forestDownload').disabled=false;\n tell('forestPacketStatus','Free Graph v0 seed packet: '+forest.graph.packet_id+\n  ' · '+forest.graph.nodes.length+' nodes · '+forest.graph.links.length+\n  ' proposed links · owner state unresolved. No remote graph was updated.');\n}\n$('forestForm').addEventListener('submit',async e=>{\n e.preventDefault();\n if(!handoff){tell('forestStatus','First create the separately reviewed handoff in Step 05.');return;}\n if(!e.target.reportValidity())return;\n try{\n  const output=await composeForest(handoff,{\n   fruit:value('forestFruit'),seed:value('forestSeed'),\n   authorReviewed:$('forestReviewed').checked,\n   exportConsent:$('forestConsent').checked\n  });\n  if(output.standing!=='REVIEWED_PACKET_UNPUBLISHED'){\n   clearForest('HOLD: review and independent export consent are required.');return;\n  }\n  forest=output;\n  renderForest();\n  if(forest.seed)$('forestNextQuestion').value=forest.seed;\n  clearInvitation('Forest seed prepared. Edit the next invitation, then explicitly approve it.');\n  tell('forestStatus','Private Forest View prepared from only the reviewed text. No Free Graph server updated, no aid confirmed, no invitation sent.');\n }catch(err){clearForest(err.message||'Could not compose Forest packet.');}\n});\n$('forestDownload').addEventListener('click',()=>{\n if(!forest)return;\n privateDownload('bananagram-free-graph-v0.json',JSON.stringify(forest.graph,null,2));\n tell('forestStatus','Free Graph seed packet downloaded locally. It has NOT been accepted by an owning project or published.');\n});\nfor(const id of ['forestFruit','forestSeed','forestReviewed','forestConsent']){\n $(id).addEventListener('input',()=>{\n  if(forest)clearForest('Forest fields changed. Compose and review a new packet before exporting.');\n });\n}\n$('forestNextForm').addEventListener('submit',e=>{\n e.preventDefault();\n if(!forest){tell('forestNextStatus','First compose a reviewed Forest packet with a possible next question.');return;}\n if(!e.target.reportValidity())return;\n try{\n  successor=nextInvitation(forest,{title:value('forestNextTitle'),\n   purpose:value('forestNextQuestion'),date:value('forestNextDate'),\n   approved:$('forestNextApproval').checked});\n  $('forestNextLink').href=successor.url;\n  $('forestNextLink').hidden=false;\n  $('forestCopyInvite').disabled=false;\n  tell('forestNextStatus','A public-safe portable invitation link is ready, not sent. Opening it shares ONLY your approved new table fields.');\n }catch(err){clearInvitation(err.message||'No invitation prepared.');}\n});\nfor(const id of ['forestNextTitle','forestNextQuestion','forestNextDate']){\n $(id).addEventListener('input',()=>clearInvitation('Changed invitation fields. Review and explicitly approve them again.'));\n}\n$('forestNextApproval').addEventListener('change',()=>{\n successor=null;\n $('forestNextLink').hidden=true;\n $('forestCopyInvite').disabled=true;\n tell('forestNextStatus',$('forestNextApproval').checked?\n  'Fields approved. Press Prepare a voluntary invitation to build the link.':'Approval withdrawn; no invitation is available.');\n});\n$('forestCopyInvite').addEventListener('click',async()=>{\n if(!successor)return;\n try{\n  await navigator.clipboard.writeText(successor.url);\n  tell('forestNextStatus','Link copied. You still choose whether and with whom to share it.');\n }catch{\n  tell('forestNextStatus','Clipboard unavailable. Open the prepared link and use the browser address bar.');\n }\n});\nfunction quantity(id){\n const v=$(id).value.trim();\n if(!/^(?:0|[1-9]\\d*)(?:\\.\\d+)?$/.test(v))throw Error('Enter a nonnegative numeric quantity for '+id);\n const n=Number(v);if(!Number.isFinite(n))throw Error('Invalid quantity.');return n;\n}\nfunction occ(id,n){\n const ref=value(id);\n if(!ref)return [];\n if(!/^[a-zA-Z0-9:_-]{4,96}$/.test(ref))throw Error('Use a non-identifying occurrence reference, no personal details.');\n if(n===0)throw Error('A zero-unit occurrence is not confirmation.');\n return [{occurrenceRef:ref,confirmedUnits:n}];\n}\nfunction fieldText(r){\n return ['FIELD RETURN 001 · UNSENT HUMAN QUESTION',\n 'Source graph: '+r.sourcePacketId,'QUESTION: '+r.question,\n 'ASK: '+r.request,'WHAT WOULD PROVE IT: '+r.evidenceQuestion,\n 'UNKNOWN: '+r.unresolved,'STATUS: No steward/recipient authenticated.',\n 'BOUNDARY: Not a receipt, consent, or authority to contact others.'].join('\\n\\n');\n}\n$('fieldRequestForm').addEventListener('submit',e=>{\n e.preventDefault();\n if(!forest){tell('fieldRequestStatus','Prepare a reviewed Forest seed in Step 06 first.');return;}\n if(!e.target.reportValidity())return;\n try{\n  const output=prepareFieldRequest(forest,{reviewApproved:$('fieldApproved').checked,\n   ask:value('fieldAsk'),whatWouldProveIt:value('fieldProof'),uncertainty:value('fieldFog')});\n  if(output.standing!=='REQUEST_DRAFT_UNSENT'){\n   clearField('HOLD: approve the exact field question before preparing it.');return;\n  }\n  fieldRequest=output;fieldReview=null;\n  $('fieldDownload').disabled=false;$('fieldCopy').disabled=false;$('fieldReviewDownload').disabled=true;\n  tell('fieldRequestPreview',fieldText(output));\n  tell('fieldReviewPreview','No claimed source evidence reviewed yet.');\n  tell('fieldRequestStatus','Private question prepared. You choose whether to ask anybody. No message sent.');\n  tell('fieldCheckStatus','');\n }catch(err){clearField(err.message||'Cannot prepare witness request.');}\n});\nfor(const id of ['fieldAsk','fieldProof','fieldFog']){\n $(id).addEventListener('input',()=>{if(fieldRequest)clearField('Question changed; review and approve again.');});\n}\n$('fieldApproved').addEventListener('change',()=>{\n if(fieldRequest)clearField('Approval changed; review again before preparing.');\n});\nfunction fieldInvitation(r){\n return [\n  'A question for a willing community steward',\n  '',\n  r.request,\n  '',\n  'The particular thing we would like to verify:',\n  r.evidenceQuestion,\n  '',\n  'What we do NOT yet know:',\n  r.unresolved,\n  '',\n  'Would exploring this question be useful to you? There is no commitment to participate.',\n  'Please say no or not yet if that is more useful.',\n  '',\n  'This is an independent community inquiry, not an official request or claim of completed aid.'\n ].join('\\n');\n}\n$('fieldCopy').addEventListener('click',async()=>{\n if(!fieldRequest)return;\n try{\n  await navigator.clipboard.writeText(fieldInvitation(fieldRequest));\n  tell('fieldRequestStatus','Voluntary request copied. You choose whether and to whom to send it. Nothing was sent here.');\n }catch{\n  tell('fieldRequestStatus','Clipboard permission unavailable. You can select the prepared question or save your private request.');\n }\n});\n$('fieldDownload').addEventListener('click',()=>{\n if(!fieldRequest)return;\n privateDownload('bananagram-private-witness-request.json',JSON.stringify(fieldRequest,null,2));\n tell('fieldRequestStatus','Private request saved locally; nothing was transmitted.');\n});\n$('fieldSecondEnabled').addEventListener('change',()=>{\n $('fieldSecondFields').hidden=!$('fieldSecondEnabled').checked;\n fieldReview=null;$('fieldReviewDownload').disabled=true;\n tell('fieldCheckStatus','Link configuration changed; inspect again.');\n});\n$('fieldCheckForm').addEventListener('submit',e=>{\n e.preventDefault();\n if(!fieldRequest){tell('fieldCheckStatus','Prepare a witness question first.');return;}\n if(!e.target.reportValidity())return;\n try{\n  const a=quantity('fieldConfirmed'),b=quantity('fieldReported'),target=quantity('fieldQuantity');\n  const links=[];\n  if(a>0||value('fieldOccurrence'))links.push({\n    claimedConfirmedUnits:a,occurrences:occ('fieldOccurrence',a)\n  });\n  if($('fieldSecondEnabled').checked){\n   const n=quantity('fieldSecondConfirmed');\n   links.push({claimedConfirmedUnits:n,occurrences:occ('fieldSecondOccurrence',n)});\n  }\n  fieldReview=inspectClaimedEvidence(fieldRequest,{\n   stewardResponse:value('fieldSteward'),requirement:value('fieldRequirement'),\n   requestedUnits:target,unit:value('fieldUnit'),helperReportedUnits:b,\n   links,statusFresh:$('fieldStatusFresh').checked\n  });\n  $('fieldReviewDownload').disabled=false;\n  const q=fieldReview.quantity;\n  tell('fieldReviewPreview',[\n   'FIELD RETURN · '+fieldReview.standing,\n   'Claimed source count: '+q.claimedConfirmationLowerBound+' '+q.unit+' (unverified)',\n   'Accounting basis: '+q.confirmationBasis,\n   'Exact across submitted links: '+(q.confirmedUnitsExact?'yes within the claim':'NO; conservatively bounded'),\n   'Helper report only: '+q.helperReported+' '+q.unit,\n   'Residual: '+(q.residualUpperBound===null?'unknown':q.residualUpperBound+' '+q.unit),\n   'Warnings: '+(fieldReview.warnings.length?fieldReview.warnings.join('; '):'Independent owner check still required'),\n   'Actual physical provision verified: NO.',\n   fieldReview.nextGate||fieldReview.humanDecision\n  ].join('\\n\\n'));\n  tell('fieldCheckStatus','Local claimed-status review prepared. Owner confirmation still required.');\n }catch(err){fieldReview=null;$('fieldReviewDownload').disabled=true;tell('fieldCheckStatus',err.message||'Could not inspect claimed evidence.');}\n});\nfor(const id of ['fieldSteward','fieldRequirement','fieldQuantity','fieldUnit','fieldReported','fieldConfirmed',\n 'fieldOccurrence','fieldSecondConfirmed','fieldSecondOccurrence','fieldStatusFresh']){\n $(id).addEventListener('input',()=>{\n  if(fieldReview){fieldReview=null;$('fieldReviewDownload').disabled=true;tell('fieldCheckStatus','Claim changed; inspect it again.');}\n });\n}\n$('fieldReviewDownload').addEventListener('click',()=>{\n if(!fieldReview)return;\n privateDownload('bananagram-private-field-review.json',JSON.stringify(fieldReview,null,2));\n tell('fieldCheckStatus','Local review downloaded, not a confirmed Jubilee receipt.');\n});\n$('fieldTrialCopy').addEventListener('click',async()=>{\n const note=[\n  'Would you help test a small community cooperation experiment?',\n  '',\n  'We are checking whether two independent, consenting members can exchange',\n  'a message in a private Campfire, while a third independent nonmember',\n  'is correctly prevented from reading or posting.',\n  '',\n  'This is a voluntary software field test—not a request for personal stories,',\n  'private case files, passwords, money, or access to anyone else’s account.',\n  '',\n  'The second phase can test one small Help Slip only with the relevant',\n  'person’s permission. A helper report is not counted as completed aid.',\n  '',\n  'The current test card is at:',\n  'https://github.com/the-static-collective/BananaSpork/blob/feat/field-specimen-independent-proof-002/docs/field-specimen-002.md',\n  '',\n  'Interested? It is also completely fine to decline.'\n ].join('\\n');\n try{\n  await navigator.clipboard.writeText(note);\n  tell('fieldTrialStatus','Invitation copied. You decide whether and who to ask. No outreach has occurred here.');\n }catch{\n  tell('fieldTrialStatus','Clipboard unavailable. You can open the field card and share only if you choose.');\n }\n});\n$('printPrivate').addEventListener('click',()=>window.print());\nrender();\n\n";
export const GRAM = "// BANANAGRAM PORTABLE-001 · no network, auth, ledger writes, or public posting.\nexport const GRAM='bananagram.portable-proposal/v0';\nexport const RETURN='bananagram.local-return/v0';\nexport const LINKS=Object.freeze(['makes_possible','learned_from','grafted_into','left_behind','composted_into','harvested_by']);\nconst REFS=/^[a-z][a-z0-9:_-]{7,95}$/;\nconst KINDS=new Set(['need','question','offer','experiment']);\nconst SOURCES=new Set(['heard_from_someone','observed_by_author','document_unreviewed','local_test']);\nconst safe=(v,min=0,max=500)=>{\n if(typeof v!=='string')throw Error('TEXT_REQUIRED');\n const s=v.replace(/[\\x00-\\x1f\\x7f]/g,' ').trim().replace(/\\s+/g,' ');\n if(s.length<min||s.length>max)throw Error('TEXT_LENGTH');\n return s;\n};\nconst ref=(v)=>{if(typeof v!=='string'||!REFS.test(v))throw Error('OPAQUE_REFERENCE_REQUIRED');return v;};\nconst copy=(v)=>JSON.parse(JSON.stringify(v));\nconst check=(v)=>{if(!v||v.schema!==GRAM||v.standing!=='LOCAL_PROPOSAL')throw Error('INVALID_GRAM');};\nconst append=(g,key,v)=>{check(g);const out=copy(g);out.previousRevision=g.revision;out.revision++;out[key].push(v);return out;};\nexport function createGram({sourceRef,kind='question',need,offeringBack='',ifThisSucceeds,question=''}){\n if(!KINDS.has(kind))throw Error('INVALID_KIND');\n return {schema:GRAM,standing:'LOCAL_PROPOSAL',scope:'this-device',sourceRef:ref(sourceRef),\n  revision:1,previousRevision:null,kind,need:safe(need,12,500),offeringBack:safe(offeringBack,0,240),\n  ifThisSucceeds:safe(ifThisSucceeds,12,300),question:safe(question,0,300),\n  reciprocity:'VOLUNTARY_NOT_REQUIRED',trace:[],tensions:[],relations:[],\n  authority:{actorAuthenticated:false,stewardAccepted:false,canonicalWrite:false,\n    transportSent:false,delivered:false,published:false}};\n}\nexport function addTrace(g,{statement,sourceType='heard_from_someone',sourceRef=null}){\n if(!SOURCES.has(sourceType))throw Error('INVALID_TRACE_TYPE');\n return append(g,'trace',{statement:safe(statement,12,450),sourceType,\n  sourceRef:sourceRef?ref(sourceRef):null,standing:'REPORTED_NOT_CONFIRMED'});\n}\nexport function addTension(g,{oneView,otherView,unresolvedQuestion}){\n return append(g,'tensions',{oneView:safe(oneView,10,320),otherView:safe(otherView,10,320),\n   unresolvedQuestion:safe(unresolvedQuestion,10,320),standing:'OPEN_NOT_RESOLVED'});\n}\nexport function linkNearby(g,{verb,targetRef,why}){\n if(!LINKS.includes(verb))throw Error('INVALID_BANANAGRAM_LINK');\n const target=ref(targetRef);\n if(target===g.sourceRef)throw Error('SELF_LINK_REFUSED');\n return append(g,'relations',{verb,targetRef:target,why:safe(why,12,240),\n   standing:'LOCAL_CANDIDATE',freeGraphAdmitted:false});\n}\nexport function selectFirstYes(g,{selected,prepareNow,permissionQuestion,proofOfReturn}){\n check(g);\n if(selected!==true)return {schema:'bananagram.first-yes/v0',standing:'HOLD_SELECTION_REQUIRED'};\n return {schema:'bananagram.first-yes/v0',standing:'SELECTED_PLAN_ONLY',sourceRef:g.sourceRef,\n  revision:g.revision,prepareNow:safe(prepareNow,12,320),\n  permissionQuestion:safe(permissionQuestion,12,320),\n  proofOfReturn:safe(proofOfReturn,12,320),\n  authority:{execute:false,stewardPermission:false,canonicalReceipt:false,notifications:false}};\n}\nexport function makeReturn(g,{reviewed,fruit='',seed='',compost=''}){\n check(g);\n if(reviewed!==true)return {schema:RETURN,standing:'HOLD_HUMAN_REVIEW_REQUIRED'};\n const a=safe(fruit,0,300),b=safe(seed,0,300),c=safe(compost,0,300);\n if(!a&&!b&&!c)throw Error('EMPTY_RETURN');\n return {schema:RETURN,standing:'AUTHOR_REPORTED_LOCAL_RETURN',sourceRef:g.sourceRef,\n  revision:g.revision,fruit:{text:a,evidence:'SELF_REPORT',confirmed:false},\n  seed:{text:b,selectionAuthority:false,crossingAuthority:false},\n  compost:{text:c,authority:false},openTensions:g.tensions.length,\n  consequenceReceipt:null,successorTableInvite:null};\n}\nexport function formatCard(g,ret=null){\n check(g);\n if(ret && (ret.schema!==RETURN||ret.sourceRef!==g.sourceRef||ret.revision!==g.revision))\n   throw Error('STALE_OR_WRONG_RETURN');\n const lines=['BANANAGRAM · PRIVATE, UNSENT PROPOSAL','Revision '+g.revision,\n '', 'NEEDS',g.need,'',\n 'OFFERING BACK (VOLUNTARY; NEVER OWED)',g.offeringBack||'None specified','',\n 'IF THIS SUCCEEDS, WHAT BECOMES POSSIBLE NEXT?',g.ifThisSucceeds,'',\n 'QUESTION',g.question||'Unknown','',\n 'TRACES — NOT CONFIRMED',...g.trace.map(t=>'- '+t.statement+' ['+t.sourceType+']'),'',\n 'TENSIONS — KEEP BOTH PERSPECTIVES',...g.tensions.map(t=>'- '+t.oneView+' / '+t.otherView+' · '+t.unresolvedQuestion),'',\n 'POSSIBLE LINKS — NOT FREE GRAPH ADMISSIONS',...g.relations.map(x=>'- '+x.verb+' → '+x.targetRef+': '+x.why)];\n if(ret)lines.push('','RETURN — '+ret.standing,'FRUIT (AUTHOR REPORT): '+ret.fruit.text,\n   'SEED (NOT SELECTED): '+ret.seed.text,'COMPOST: '+ret.compost.text);\n lines.push('','No message sent. No Jubilee receipt. No partner enrolled. No verified delivery.');\n return lines.join('\\n');\n}\n";
export const PARTICIPATION = "/** Illustrative, PURE boundary; no network, no database, no Telegram or authority writes. */\nexport const VERSION = 'graft/participation-bridge-candidate-v0';\nconst TOKEN = /(?:^|[^\\w])(?:[A-Za-z0-9_-]{43})(?:$|[^\\w])/;\nconst CONTACT = /[\\w.+-]+@[\\w.-]+\\.[A-Za-z]{2,}|(?:\\+?1[ .-]?)?\\(?\\d{3}\\)?[ .-]?\\d{3}[ .-]?\\d{4}|https?:\\/\\/|www\\./i;\nconst DESTINATIONS = new Set(['campfire-review','telegram-porch-draft','first-yes']);\nconst KINDS = new Set(['question','need','offer','experiment']);\nfunction clean(t, max){\n if(typeof t !== 'string') throw new TypeError('TEXT_REQUIRED');\n const v=t.replace(/[\\x00-\\x1f\\x7f]/g,' ').replace(/\\s+/g,' ').trim();\n if(v.length<12||v.length>max) throw new TypeError('TEXT_LENGTH');\n if(CONTACT.test(v)||TOKEN.test(v)) throw new TypeError('PRIVATE_CONTENT_REFUSED');\n return v;\n}\n/**\n * input: {sourceRef, status, kind, destination, redactedSummary,\n *         consentToExport, reviewedByHuman, sourceVisibility}\n * The source record is NEVER copied; passed redactedSummary must be separately\n * consented and reviewed. No source invite URLs or secret tokens are accepted.\n */\nexport function prepareCandidate(input) {\n if(!input || typeof input !== 'object' || Array.isArray(input))throw new TypeError('OBJECT_REQUIRED');\n if(typeof input.sourceRef!=='string' || !/^[a-z0-9:-]{8,96}$/.test(input.sourceRef))throw new TypeError('OPAQUE_REFERENCE_REQUIRED');\n if(input.status!=='participating')return Object.freeze({schema:VERSION,standing:'HOLD_LOCAL',why:'NOT_AN_ACTIVE_CONTRIBUTION'});\n if(input.consentToExport!==true)return Object.freeze({schema:VERSION,standing:'HOLD_LOCAL',why:'NO_EXPORT_CONSENT'});\n if(input.reviewedByHuman!==true)return Object.freeze({schema:VERSION,standing:'HOLD_LOCAL',why:'NEEDS_HUMAN_REVIEW'});\n if(input.sourceVisibility!=='eligible-for-explicit-export')return Object.freeze({schema:VERSION,standing:'HOLD_LOCAL',why:'SOURCE_SCOPE_REFUSES_EXPORT'});\n if(!DESTINATIONS.has(input.destination)||!KINDS.has(input.kind))throw new TypeError('UNSUPPORTED_SEAM');\n const summary=clean(input.redactedSummary,240);\n return Object.freeze({\n  schema:VERSION,\n  standing:'PROPOSE_ONLY',\n  source:{opaqueRef:input.sourceRef,veracity:'UNVERIFIED_SELF_REPORT',scope:'REVIEWED_REDACTION'},\n  target:input.destination,\n  candidate:{kind:input.kind,summary},\n  authority:{actorAuthenticated:false,circleMembership:false,consentToPerform:false,\n    canonicalWrite:false,transportDispatched:false,partnerCommitted:false,\n    provisionConfirmed:false,publicationApproved:false},\n  nextGate:'A separately authenticated, authorized human must choose whether and where to submit this proposal.'\n });\n}\n";
export const REENTRY = "import {GRAM} from '?asset=gram';\nimport {prepareCandidate,VERSION} from '?asset=participation';\n/** Explicit consented, human-reviewed Gram -> inert proposal crossing. */\nexport function proposeGramCrossing(gram,{\n participationConfirmedByAuthor=false,consentToExport=false,\n reviewedByHuman=false,redactedSummary='',kind='question',destination='first-yes'\n}={}){\n if(!gram||gram.schema!==GRAM||gram.scope!=='this-device'||gram.standing!=='LOCAL_PROPOSAL')\n   throw Error('INVALID_SOURCE_GRAM');\n if(!Number.isInteger(gram.revision)||gram.revision<1)throw Error('INVALID_GRAM_REVISION');\n if(!participationConfirmedByAuthor||!consentToExport||!reviewedByHuman)\n  return Object.freeze({schema:VERSION,standing:'HOLD_LOCAL',why:\n    !participationConfirmedByAuthor?'NO_AUTHOR_SUBMISSION':\n    !consentToExport?'NO_EXPORT_CONSENT':'NEEDS_HUMAN_REVIEW'});\n const sourceRef=gram.sourceRef+':r'+gram.revision;\n // IMPORTANT: no automatic copying of need, offeringBack, trace, tension,\n // relation, personal history, or link token. A new redaction is required.\n return prepareCandidate({sourceRef,status:'participating',consentToExport:true,\n  reviewedByHuman:true,sourceVisibility:'eligible-for-explicit-export',\n  redactedSummary,kind,destination});\n}\n";
export const FOREST = "/**\n * FOREST-001 · from a reviewed BananaGram proposal to a portable\n * Free Graph v0 SEED packet and an optional independent Seventh Table invite.\n * NO database, messaging, membership, authority or publication side effects.\n */\nexport const FOREST_SCHEMA='bananagram.forest-projection/v0';\nexport const GRAPH_SCHEMA='free-graph.packet/v0';\nconst CONTACT=/[\\w.+-]+@[\\w.-]+\\.[a-z]{2,}|(?:\\+?1[ .-]?)?\\(?\\d{3}\\)?[ .-]?\\d{3}[ .-]?\\d{4}|https?:\\/\\/|www\\.|(?:^|[^\\w])[a-z0-9_-]{43}(?:[^\\w]|$)/i;\nfunction reviewed(t,max=240,min=12){\n if(typeof t!=='string')throw Error('TEXT_REQUIRED');\n const s=t.replace(/\\s+/g,' ').trim();\n if(s.length<min||s.length>max||/[\\u0000-\\u001f\\u007f]/.test(t))throw Error('TEXT_LENGTH');\n if(CONTACT.test(s))throw Error('PRIVATE_CONTENT_REFUSED');\n return s;\n}\nfunction canonical(o){\n if(Array.isArray(o))return '['+o.map(canonical).join(',')+']';\n if(o&&typeof o==='object')return '{'+Object.keys(o).sort().map(k=>JSON.stringify(k)+':'+canonical(o[k])).join(',')+'}';\n return JSON.stringify(o);\n}\nfunction assertCrypto(cryptoProvider){\n if(!cryptoProvider?.subtle?.digest || !cryptoProvider?.getRandomValues)throw Error('CRYPTO_REQUIRED');\n}\nasync function digest(value,cryptoProvider){\n const data=new TextEncoder().encode(value);\n const bytes=new Uint8Array(await cryptoProvider.subtle.digest('SHA-256',data));\n return Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');\n}\nasync function record(prefix,body,c){\n return {...body,id:prefix+':sha256:'+await digest(canonical(body),c)};\n}\nfunction assertCandidate(candidate){\n if(candidate?.standing!=='PROPOSE_ONLY'||candidate.schema!=='graft/participation-bridge-candidate-v0')\n   throw Error('REVIEWED_GRAM_PROPOSAL_REQUIRED');\n if(candidate.source?.scope!=='REVIEWED_REDACTION' || candidate.source.veracity!=='UNVERIFIED_SELF_REPORT')\n   throw Error('UNTRUSTED_SOURCE');\n if(candidate.authority?.canonicalWrite!==false || candidate.authority?.publicationApproved!==false)\n   throw Error('CANNOT_IMPORT_AUTHORITY');\n const summary=reviewed(candidate.candidate?.summary,240);\n return summary;\n}\n/**\n * Forest is scoped to author-selected, explicitly reviewed PUBLIC-SAFE text.\n * The private Gram, local traces, tensions, and original credentials never enter.\n *\n * fruit is a SELF-REPORT, not independent human witness or confirmed consequence.\n * A separate owning-world receipt would be required to claim verified fruit.\n */\nexport async function composeForest(candidate,{fruit='',seed='',authorReviewed=false,exportConsent=false}={},cryptoProvider=globalThis.crypto){\n assertCrypto(cryptoProvider);\n const question=assertCandidate(candidate);\n if(!authorReviewed||!exportConsent)return {schema:FOREST_SCHEMA,standing:'HOLD_LOCAL',why:!authorReviewed?'HUMAN_REVIEW_REQUIRED':'NO_GRAPH_EXPORT_CONSENT'};\n const fruitText=fruit.trim()?reviewed(fruit,240):'';\n const seedText=seed.trim()?reviewed(seed,240):'';\n if(!fruitText&&!seedText)throw Error('FRUIT_OR_SEED_REQUIRED');\n const excerpt=[question,...(fruitText?['AUTHOR REPORT (unconfirmed): '+fruitText]:[]),\n   ...(seedText?['POSSIBLE NEXT QUESTION (unapproved): '+seedText]:[])].join('\\n');\n const src=await record('fgs',{\n  source_class:'conversation-witness',authority:'none',\n  access:'public',export:'portable',acquisition:'voluntary reviewed Pocket text only',\n  digest:'sha256:'+await digest(excerpt,cryptoProvider),excerpt,\n  locator:{system:'BananaGram Pocket',coordinate:'separate reviewed redaction only',\n    revision:'author-reviewed portable seed v0',resolution:'locally assembled public-safe text'}\n },cryptoProvider);\n const base={source_ids:[src.id]};\n const questionNode=await record('fgn',{kind:'question',label:question,status:'unresolved',...base},cryptoProvider);\n const nodes=[questionNode],links=[];\n if(fruitText){\n  const n=await record('fgn',{kind:'testimony',label:fruitText,status:'proposed',\n   extensions:{evidence:'author-self-report-only',confirmed:false},...base},cryptoProvider);\n  nodes.push(n);\n  links.push(await record('fgl',{from:questionNode.id,to:n.id,verb:'connects',\n   qualifier:'author-reported-fruit-not-independent-witness',status:'proposed',\n   authority:'none',...base},cryptoProvider));\n }\n if(seedText){\n  const n=await record('fgn',{kind:'question',label:seedText,status:'proposed',\n   extensions:{selection_authority:false,invitation_created:false},...base},cryptoProvider);\n  nodes.push(n);\n  links.push(await record('fgl',{from:questionNode.id,to:n.id,verb:'connects',\n   qualifier:'proposes-next-question-no-successor-authority',status:'proposed',\n   authority:'none',...base},cryptoProvider));\n }\n const packet={\n  schema:GRAPH_SCHEMA,\n  purpose:'Carry one explicitly reviewed question, author-reported result, and possible next question without claim promotion.',\n  modes:['re-enter','seed'],\n  scope:{task:'Inspect a consented portable question and choose whether to ask another',\n   worlds:['BananaGram Pocket','Free Graph proposal substrate'],as_of:'local author review; no authoritative owner head'},\n  sources:[src],nodes,links,\n  task_world_cut:{\n   status:'unresolved',selected_ids:[src.id,...nodes.map(x=>x.id),...links.map(x=>x.id)],\n   owner_head_source_ids:[],\n   omitted:[{door:'Independent human/owning-institution confirmation',\n    reason:'No source-owner gate or actual completed aid receipt was inspected.'}],\n   rationale:'Public-safe self-report is sufficient for seeding a question, not for testing, adopting or confirming its factual claims.'\n  },\n  residual_fog:['No independent witness or owning-world receipt supplied.',\n   'No one has accepted the possible successor question.'],\n  non_imports:['No private Gram, personal identity, invitation credential, household story or participant contact was transferred.',\n   'No institutional acceptance, actual aid delivery or public publishing decision can be inferred.'],\n  extensions:{projection:FOREST_SCHEMA,authority:'none',next_invitation_automated:false}\n };\n packet.packet_id='fgp:sha256:'+await digest(canonical(packet),cryptoProvider);\n return {\n  schema:FOREST_SCHEMA,standing:'REVIEWED_PACKET_UNPUBLISHED',\n  question,fruit:fruitText,seed:seedText,\n  evidence:fruitText?'AUTHOR_REPORTED_UNCONFIRMED':'NONE',\n  graph:packet,\n  authority:{ownerAdopted:false,verifiedFulfillment:false,published:false,\n   invitationCreated:false,peopleContacted:false,sourceCredentialTransferred:false}\n };\n}\n/**\n * Reuse the native Seventh Table v:1 card from the existing /tables/ flow.\n * This creates only a URL representing an invitation PROPOSAL, never a hosted table.\n */\nexport function nextInvitation(forest,{title,purpose,date,approved=false}={},cryptoProvider=globalThis.crypto){\n assertCrypto(cryptoProvider);\n if(forest?.standing!=='REVIEWED_PACKET_UNPUBLISHED'||forest?.graph?.schema!==GRAPH_SCHEMA)\n   throw Error('REVIEWED_FOREST_REQUIRED');\n if(!forest.seed)throw Error('NO_SEED_NO_SUCCESSOR');\n if(approved!==true)throw Error('INVITATION_REVIEW_REQUIRED');\n const t=reviewed(title,84,3),p=reviewed(purpose,270,5);\n if(!/^\\d{4}-\\d{2}-\\d{2}$/.test(date)||Number.isNaN(Date.parse(date+'T12:00:00Z'))||\n    new Date(date+'T12:00:00Z').toISOString().slice(0,10)!==date)\n   throw Error('INVALID_CALENDAR_DATE');\n const bytes=cryptoProvider.getRandomValues(new Uint8Array(8));\n const id=Array.from(bytes,b=>b.toString(36).padStart(2,'0')).join('').slice(0,10).toUpperCase();\n const card={v:1,id,title:t,purpose:p,date,time:'',venue:'',host:'',parent:'',chain:[]};\n const encoded=new TextEncoder().encode(JSON.stringify(card));\n const base64=btoa(String.fromCharCode(...encoded)).replace(/\\+/g,'-').replace(/\\//g,'_').replace(/=+$/,'');\n if(base64.length>5000)throw Error('INVITATION_TOO_LARGE');\n return {schema:'bananagram.seventh-table-proposal/v0',standing:'LINK_PREPARED_NOT_SENT',\n  url:'https://abundent.org/tables/#invite='+base64,card,\n  authority:{tableCreated:false,contactSent:false,participantsInherited:false,\n   ownerEndorsement:false,fruitVerified:false}};\n}\n";
export const WITNESS = "/**\n * FIELD-RETURN-001 · BananaGram's witness request membrane.\n *\n * In this portable UI there are NO verified identities, Campfire members, owner\n * database reads, real-world delivery witnesses or independently signed receipts.\n * Consequently this file can PREPARE a request and assess a claimed snapshot,\n * but can NEVER mark an actual outcome CONFIRMED.\n *\n * Mirrors BananaSpork FIELD-SPECIMEN-001 and RETURN-OF-THE-HELP-SLIP-001:\n * report != confirmation; record ID != physical occurrence;\n * ambiguous multi-Campfire confirmation != sum; subset != whole source request.\n */\nexport const REQUEST_SCHEMA='bananagram.field-witness-request/v0';\nexport const INSPECT_SCHEMA='bananagram.field-evidence-review/v0';\nconst CONTACT=/[\\w.+-]+@[\\w.-]+\\.[a-z]{2,}|(?:\\+?1[ .-]?)?\\(?\\d{3}\\)?[ .-]?\\d{3}[ .-]?\\d{4}|https?:\\/\\/|www\\.|(?:^|[^\\w])[a-z0-9_-]{43}(?:[^\\w]|$)/i;\nfunction safe(v,min,max){\n if(typeof v!=='string')throw Error('FIELD_TEXT_REQUIRED');\n const s=v.trim().replace(/\\s+/g,' ');\n if(s.length<min||s.length>max||/[\\u0000-\\u001f\\u007f]/.test(v))throw Error('FIELD_TEXT_LENGTH');\n if(CONTACT.test(s))throw Error('PRIVATE_CONTACT_REFUSED');\n return s;\n}\nfunction number(x){\n if(typeof x!=='number'||!Number.isFinite(x)||x<0)throw Error('NONNEGATIVE_QUANTITY_REQUIRED');\n return x;\n}\nconst almost=(a,b)=>Math.abs(a-b)<=Number.EPSILON*Math.max(1,Math.abs(a),Math.abs(b))*8;\n/** A question that can be given to an authorized steward, never a command. */\nexport function prepareFieldRequest(forest,{\n reviewApproved=false,ask='',whatWouldProveIt='',uncertainty=''\n}={}){\n if(forest?.standing!=='REVIEWED_PACKET_UNPUBLISHED' ||\n  forest?.graph?.schema!=='free-graph.packet/v0' ||\n  forest?.authority?.verifiedFulfillment!==false)\n  throw Error('REVIEWED_FOREST_REQUIRED');\n if(reviewApproved!==true)return Object.freeze({\n  schema:REQUEST_SCHEMA,standing:'HOLD_NO_REQUEST_APPROVAL'\n });\n const question=safe(forest.question,12,240);\n const text=safe(ask,12,240);\n const proof=safe(whatWouldProveIt,12,240);\n const fog=safe(uncertainty,12,240);\n return Object.freeze({\n  schema:REQUEST_SCHEMA,standing:'REQUEST_DRAFT_UNSENT',\n  sourcePacketId:safe(forest.graph.packet_id,10,96),\n  question,request:text,evidenceQuestion:proof,unresolved:fog,\n  status:'NO_OWNER_OR_RECIPIENT_VERIFIED',\n  noClaimOfPhysicalProvision:true,\n  nextHumanGate:'An actual authorized steward chooses whether to review this question.',\n  authority:{stewardConsented:false,requestDelivered:false,\n   helperReportConfirmed:false,receiptVerified:false,\n   supplyDelivered:false,sharedPublicly:false}\n });\n}\n/**\n * Inspect a manually transcribed snapshot from a proposed source.\n * A snapshot, even with an apparent receipt ID, is NOT verified by this app:\n * owner-current authentication + receipt binding must happen in NanaSpork.\n *\n * Source requirements are independent; links must not multiply demand.\n * The return reports conservative evidence-state, not a canonical count.\n */\nexport function inspectClaimedEvidence(request,{\n stewardResponse='not-asked',requirement='',requestedUnits=0,unit='',\n helperReportedUnits=0,links=[],statusFresh=false,\n ownerReceiptClaim='',independentRecipientConfirmation=false\n}={}){\n if(request?.schema!==REQUEST_SCHEMA||request.standing!=='REQUEST_DRAFT_UNSENT')\n  throw Error('FIELD_REQUEST_REQUIRED');\n if(!['not-asked','declined','accepted-to-review','no-need'].includes(stewardResponse))\n  throw Error('INVALID_STEWARD_RESPONSE');\n if(!Array.isArray(links)||links.length>8)throw Error('TOO_MANY_LINKS');\n const q=safe(requirement,5,160),label=safe(unit,1,36);\n const target=number(requestedUnits),reported=number(helperReportedUnits);\n const seen=new Map(),warnings=[],counts=[];\n let allAttributable=links.length>0;\n for(const link of links){\n  if(!link||typeof link!=='object')throw Error('BAD_SOURCE_LINK');\n  const confirmed=number(link.claimedConfirmedUnits);\n  counts.push(confirmed);\n  const occurrences=link.occurrences;\n  if(!Array.isArray(occurrences)||!occurrences.length){\n   if(confirmed>0)allAttributable=false;\n   continue;\n  }\n  let subTotal=0;\n  for(const occ of occurrences){\n   if(!occ||typeof occ!=='object')throw Error('BAD_OCCURRENCE');\n   const ref=safe(occ.occurrenceRef,4,96),n=number(occ.confirmedUnits);\n   if(n===0)throw Error('ZERO_OCCURRENCE_REFUSED');\n   subTotal+=n;\n   if(seen.has(ref)&&!almost(seen.get(ref),n)){\n    allAttributable=false;warnings.push('CONFLICTING_OCCURRENCE_AMOUNT');\n   }else seen.set(ref,n);\n  }\n  if(!almost(subTotal,confirmed)){\n   allAttributable=false;warnings.push('OCCURRENCE_TOTAL_MISMATCH');\n  }\n }\n let lowerBound=0,basis='none',exact=false;\n if(links.length===1){\n  lowerBound=counts[0];basis='single-link';exact=true;\n }else if(links.length>1&&allAttributable){\n  lowerBound=[...seen.values()].reduce((x,y)=>x+y,0);\n  basis='deduplicated-occurrences';exact=true;\n }else if(links.length>1){\n  lowerBound=Math.max(...counts);\n  basis='ambiguous-multi-link-lower-bound';exact=false;\n  warnings.push('CONFIRMATIONS_NOT_SAFELY_SUMMABLE');\n }\n if(stewardResponse==='declined'||stewardResponse==='no-need'){\n  // Respect refusal or lack of need without turning a report into an action.\n  return Object.freeze({schema:INSPECT_SCHEMA,\n   standing:'STOP_OR_RETURN_TO_AUTHOR',stewardResponse,\n   question:request.question,proposedRequirement:q,\n   quantity:{unit:label,requested:target,helperReported:reported,\n    claimedConfirmationLowerBound:lowerBound,confirmedUnitsExact:exact,\n    confirmationBasis:basis,residualUpperBound:exact?Math.max(target-lowerBound,0):null},\n   warnings:[...warnings,'NO_FURTHER_ACTION_WITHOUT_NEW_PERMISSION'],\n   ownerReceiptReviewed:false,physicalProvisionVerified:false,\n   humanDecision:'Do not contact suppliers, send a new ask, or publish a success claim.'});\n }\n if(reported>0&&lowerBound===0)warnings.push('HELPER_REPORT_HAS_NO_CONFIRMATION');\n if(links.length===0)warnings.push('NO_CONFIRMATION_RECORDS');\n if(!statusFresh)warnings.push('CLAIMED_STATUS_NOT_CURRENT');\n if(!ownerReceiptClaim.trim())warnings.push('NO_OWNER_RECEIPT_REFERENCE');\n if(independentRecipientConfirmation)warnings.push('SELF_ATTESTED_RECIPIENT_CONFIRMATION_NOT_IDENTITY_VERIFIED');\n return Object.freeze({schema:INSPECT_SCHEMA,\n  standing:'OWNER_RECEIPT_REVIEW_REQUIRED',\n  stewardResponse,\n  question:request.question,proposedRequirement:q,\n  quantity:{\n   unit:label,requested:target,helperReported:reported,\n   claimedConfirmationLowerBound:lowerBound,\n   confirmedUnitsExact:exact,\n   confirmationBasis:basis,\n   residualUpperBound:exact?Math.max(target-lowerBound,0):null\n  },\n  warnings,sourceReceiptReference:ownerReceiptClaim.trim()?safe(ownerReceiptClaim,4,96):null,\n  ownerReceiptReviewed:false,physicalProvisionVerified:false,\n  authorization:'NONE_FROM_THIS_PACKET',\n  nextGate:'An authenticated owner must inspect the source-current receipt and actual beneficiary/recipient confirmation before any confirmation or published consequence.'\n });\n}\n/** Preserve public-safe observations only; never emit a verified Free Graph edge. */\nexport function fieldReturnNote(review,{authorReviewed=false,summary=''}={}){\n if(review?.schema!==INSPECT_SCHEMA)throw Error('FIELD_REVIEW_REQUIRED');\n if(!authorReviewed)return {standing:'HOLD_AUTHOR_REVIEW'};\n const text=safe(summary,12,240);\n return Object.freeze({\n  schema:'bananagram.field-return-note/v0',\n  standing:'PUBLIC_SAFE_UNVERIFIED_NOTE',\n  sourceStatus:review.standing,summary:text,\n  interpretation:'REPORTED_OR_UNRESOLVED_NOT_OWNER_CONFIRMED',\n  graphEffect:'NONE',nextInvite:'NONE',receiptCreated:false,\n  verifiedFulfillment:false\n });\n}\n";
